  const [count, setCount] = useState(0);

  // New object reference on every Parent render
  const options = { theme: "dark" };

  return <Child options={options} />;
}

const Child = React.memo(function Child({ options }) {
  console.log("render");
  return <div>{options.theme}</div>;
});
```

Although the contents are unchanged, this is true on every render:

```js
previousOptions !== nextOptions
```

### Fix options

**1. Memoize the object when using a memoized child:**

```jsx
