  () => ({ theme, pageSize }),
  [theme, pageSize]
);
```

**2. Pass primitive props instead:**

```jsx
<Child theme="dark" />

const Child = React.memo(function Child({ theme }) {
  return <div>{theme}</div>;
});
```

**3. Move a constant object outside the component:**

```jsx
