Use the `pg` package and create one long-lived `Pool` for the entire Node.js process.

```bash
npm install pg
```

### Pool configuration

```js
// db.js
const { Pool } = require('pg');

function intFromEnv(name, fallback) {
  const value = Number.parseInt(process.env[name] ?? '', 10);
  return Number.isFinite(value) ? value : fallback;
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum concurrent PostgreSQL connections from this process.
  max: intFromEnv('PG_POOL_MAX', 10),

  // Maximum time to wait for a connection from the pool.
  connectionTimeoutMillis: intFromEnv(
    'PG_CONNECTION_TIMEOUT_MS',
    5_000,
  ),

  // Close unused pooled connections after this period.
  idleTimeoutMillis: intFromEnv('PG_IDLE_TIMEOUT_MS', 30_000),

  // Server-side limit for each SQL statement.
  statement_timeout: intFromEnv('PG_STATEMENT_TIMEOUT_MS', 15_000),

  // End transactions that remain idle accidentally.
  idle_in_transaction_session_timeout: intFromEnv(
    'PG_IDLE_TRANSACTION_TIMEOUT_MS',
    30_000,
  ),

  keepAlive: true,
  keepAliveInitialDelayMillis: 10_000,

  application_name: process.env.SERVICE_NAME || 'node-service',

  // Use only if your PostgreSQL provider requires TLS.
  ssl:
    process.env.PGSSL === 'true'
      ? {
          // Prefer providing your provider's CA rather than disabling checks.
          rejectUnauthorized: true,
          ca: process.env.PGSSL_CA,
        }
      : undefined,
});

// Required: catches errors emitted by idle clients in the pool.
pool.on('error', (err) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: err.message,
    code: err.code,
    stack: err.stack,
  });

  // Report to monitoring here. Do not blindly crash unless your
  // application's reliability policy requires it.
});

module.exports = pool;
```

### Running ordinary queries

Prefer `pool.query()` for single statements because it automatically checks out and releases a client.

```js
// users.js
const pool = require('./db');

async function getUserById(id) {
  try {
    const result = await pool.query({
      text: `
        SELECT id, email, created_at
        FROM users
        WHERE id = $1
      `,
      values: [id],
    });

    return result.rows[0] ?? null;
  } catch (err) {
    console.error('Failed to fetch user', {
      userId: id,
      code: err.code,       // PostgreSQL SQLSTATE, if available
      message: err.message,
    });

    throw err;
  }
}

module.exports = { getUserById };
```

Always use parameters such as `$1`; do not concatenate user-controlled values into SQL.

### Transactions

When using `pool.connect()`, the client must always be released. If rollback fails, destroy that client instead of returning a potentially broken connection to the pool.

```js
const pool = require('./db');

async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();
  let releaseError;

  try {
    await client.query('BEGIN');

    // Optional transaction-specific timeout.
    await client.query(
      `SELECT set_config('statement_timeout', $1, true)`,
      ['10000'],
    );

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId],
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId],
    );

    await client.query('COMMIT');
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackErr) {
      releaseError = rollbackErr;
      err.rollbackError = rollbackErr;
    }

    console.error('Transaction failed', {
      message: err.message,
      code: err.code,
      rollbackError: err.rollbackError?.message,
    });

    throw err;
  } finally {
    // Passing an error causes pg to discard the client.
    client.release(releaseError);
  }
}
```

### Graceful shutdown

Stop accepting new requests first, then close the pool:

```js
const pool = require('./db');

let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    await pool.end();
    console.log('PostgreSQL pool closed');
    process.exitCode = 0;
  } catch (err) {
    console.error('Failed to close PostgreSQL pool', err);
    process.exitCode = 1;
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

In an HTTP server, call `server.close()` before `pool.end()` so no new handlers attempt database queries during shutdown.

### What the timeouts mean

- `connectionTimeoutMillis`: how long a caller waits to obtain or establish a pooled connection.
- `idleTimeoutMillis`: how long an unused connection remains in the pool.
- `statement_timeout`: PostgreSQL cancels statements that run too long. This is the primary query-execution timeout.
- `idle_in_transaction_session_timeout`: terminates sessions accidentally left idle inside a transaction.

A reasonable timeout hierarchy is:

```text
Connection acquisition:   5 seconds
SQL statement:            15 seconds
HTTP/request deadline:    20 seconds
Idle transaction:         30 seconds
Idle pooled connection:   30 seconds
```

### Operational considerations

- Create one pool per application process, not one per request.
- Size `max` across all instances. For example, 10 app instances with `max: 10` may open 100 database connections.
- Monitor pool saturation:

```js
console.log({
  total: pool.totalCount,
  idle: pool.idleCount,
  waiting: pool.waitingCount,
});
```

- A steadily increasing `waitingCount` indicates insufficient pool capacity, slow queries, leaked clients, or database overload.
- PostgreSQL errors expose SQLSTATE through `err.code`. Errors such as serialization failures (`40001`) or deadlocks (`40P01`) can sometimes be retried with a bounded retry count and backoff. Do not retry every database error.
- Keep TLS certificate verification enabled in production; avoid `rejectUnauthorized: false` unless there is no secure alternative.

