Calls.Text:
Using the `pg` package, create one application-wide `Pool` and reuse it for every request. Configure separate limits for acquiring a connection, idle connections, and database statement execution.

```bash
npm install pg
```

### Pool configuration

```js
// db.js (ES modules)
import pg from 'pg';

const { Pool } = pg;

function envInt(name, fallback) {
  const value = Number.parseInt(process.env[name] ?? '', 10);
  return Number.isFinite(value) ? value : fallback;
}

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Number of open connections per application instance.
  max: envInt('PG_POOL_MAX', 10),

  // Fail if a connection cannot be acquired/established in this time.
  connectionTimeoutMillis: envInt('PG_CONNECT_TIMEOUT_MS', 5_000),

  // Close unused pooled connections after this time.
  idleTimeoutMillis: envInt('PG_IDLE_TIMEOUT_MS', 30_000),

  // Server-side limit: PostgreSQL cancels statements exceeding this time.
  statement_timeout: envInt('PG_STATEMENT_TIMEOUT_MS', 15_000),

  // Client-side limit on how long pg waits for a query.
  query_timeout: envInt('PG_QUERY_TIMEOUT_MS', 17_000),

  // Prevent abandoned transactions from holding locks indefinitely.
  idle_in_transaction_session_timeout: envInt(
    'PG_IDLE_TRANSACTION_TIMEOUT_MS',
    30_000
  ),

  application_name: process.env.SERVICE_NAME ?? 'node-api',

  // Configure TLS according to your provider.
  ssl:
    process.env.NODE_ENV === 'production'
      ? {
          rejectUnauthorized: true,
          // ca: process.env.PG_CA_CERT, // Recommended when a CA is provided.
        }
      : undefined,
});

// Handles errors emitted by idle clients in the pool.
// Without this listener, an idle-client error can become an uncaught event.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
  });
});
```

Prefer a server-side `statement_timeout` because PostgreSQL itself cancels the work. Set the client-side `query_timeout` slightly higher so the server has time to return the timeout error.

### Query helper

```js
export async function query(text, params = []) {
  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      message: error.message,
      code: error.code, // PostgreSQL SQLSTATE, such as 23505
      // Avoid logging params if they may contain secrets or personal data.
    });

    throw error;
  }
}
```

Use parameterized queries:

```js
import { query } from './db.js';

const result = await query(
  'SELECT id, email FROM users WHERE id = $1',
  [userId]
);
```

For single queries, `pool.query()` automatically acquires and releases a connection.

### Transactions

Transactions must use one checked-out client. Always release it in `finally`:

```js
import { pool } from './db.js';

export async function createOrder(userId, total) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    const result = await client.query(
      `INSERT INTO orders (user_id, total)
       VALUES ($1, $2)
       RETURNING id`,
      [userId, total]
    );

    await client.query('COMMIT');
    return result.rows[0];
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('Transaction rollback failed', rollbackError);
    }

    console.error('Transaction failed', {
      message: error.message,
      code: error.code,
    });

    throw error;
  } finally {
    client.release();
  }
}
```

Do not use `pool.query('BEGIN')` followed by other `pool.query()` calls; they may run on different connections.

### Verify the connection at startup

```js
import { pool } from './db.js';

export async function verifyDatabase() {
  const client = await pool.connect();

  try {
    await client.query('SELECT 1');
    console.log('PostgreSQL connection established');
  } finally {
    client.release();
  }
}
```

Call this before accepting traffic so configuration failures are detected immediately.

### Graceful shutdown

```js
let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    await pool.end();
    process.exitCode = 0;
  } catch (error) {
    console.error('Failed to close PostgreSQL pool', error);
    process.exitCode = 1;
  }
}

process.once('SIGTERM', () => void shutdown('SIGTERM'));
process.once('SIGINT', () => void shutdown('SIGINT'));
```

### Practical guidance

- Create one pool per Node.js process, not one pool per request.
- Choose `max` based on the database connection limit and number of application instances. For example, 10 instances with `max: 10` can consume up to 100 connections.
- Handle query errors where the query is called; the pool’s `error` event is specifically for background/idle-client failures.
- Inspect `error.code` for PostgreSQL SQLSTATE values. Only retry known transient errors, such as serialization failures, and only when the operation is safe to retry.
- Never log the full `DATABASE_URL`, because it usually contains credentials.
- In production, verify TLS certificates using the provider’s CA rather than setting `rejectUnauthorized: false`.

