A common choice is [`pg`](https://node-postgres.com/) (`node-postgres`). Create one pool per Node.js process and reuse it rather than opening a new connection for every request.

```bash
npm install pg
```

### Pool configuration

```js
// db.js
import pg from 'pg';

const { Pool } = pg;

function envInt(name, fallback) {
  const value = Number.parseInt(process.env[name] ?? '', 10);
  return Number.isFinite(value) ? value : fallback;
}

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum connections opened by this Node.js process.
  max: envInt('PG_POOL_MAX', 10),

  // Fail instead of waiting indefinitely for a connection.
  connectionTimeoutMillis: envInt('PG_CONNECT_TIMEOUT_MS', 5_000),

  // Close unused connections after this period.
  idleTimeoutMillis: envInt('PG_IDLE_TIMEOUT_MS', 30_000),

  // Server-side timeout: PostgreSQL cancels statements exceeding this limit.
  statement_timeout: envInt('PG_STATEMENT_TIMEOUT_MS', 10_000),

  // Client-side fallback timeout. Keep it slightly above statement_timeout.
  query_timeout: envInt('PG_QUERY_TIMEOUT_MS', 12_000),

  keepAlive: true,
  keepAliveInitialDelayMillis: 10_000,

  application_name: process.env.SERVICE_NAME ?? 'node-api',

  // Configure this according to your provider. Do not disable certificate
  // validation in production merely to suppress TLS errors.
  ssl:
    process.env.NODE_ENV === 'production' && process.env.PG_SSL === 'true'
      ? {
          rejectUnauthorized: true,
          ca: process.env.PG_SSL_CA,
        }
      : undefined,
});

// Required: catches errors emitted by idle clients in the pool.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
    stack: error.stack,
  });

  // Send this to your logging/monitoring system. Usually do not throw here,
  // because throwing from an EventEmitter error handler can terminate Node.
});
```

Set environment variables, for example:

```env
DATABASE_URL=postgresql://app_user:secret@localhost:5432/app_db
PG_POOL_MAX=10
PG_CONNECT_TIMEOUT_MS=5000
PG_IDLE_TIMEOUT_MS=30000
PG_STATEMENT_TIMEOUT_MS=10000
PG_QUERY_TIMEOUT_MS=12000
PG_SSL=false
```

## Running ordinary queries

For single queries, prefer `pool.query()`. It automatically checks out and releases the connection:

```js
export async function getUserById(id) {
  try {
    const result = await pool.query(
      'SELECT id, email, created_at FROM users WHERE id = $1',
      [id],
    );

    return result.rows[0] ?? null;
  } catch (error) {
    if (error.code === '57014') {
      // PostgreSQL query cancellation, commonly caused by statement_timeout.
      console.warn('User query timed out', { id });
    } else {
      console.error('User query failed', {
        id,
        code: error.code,       // PostgreSQL SQLSTATE or Node network code
        message: error.message,
      });
    }

    throw error; // Let the service/API layer map it to an appropriate response.
  }
}
```

Always parameterize values using `$1`, `$2`, and so on. Do not concatenate untrusted values into SQL.

## Transactions

Transactions must use one checked-out client. Always release it in `finally`, and attempt a rollback after failures:

```js
export async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();
  let released = false;

  try {
    await client.query('BEGIN');

    // Optional shorter timeout for this specific transaction.
    await client.query(
      `SELECT set_config('statement_timeout', $1, true)`,
      ['5s'],
    );

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId],
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId],
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      // Destroy this connection instead of returning a potentially broken
      // connection to the pool.
      client.release(rollbackError);
      released = true;

      console.error('Transaction rollback failed', {
        error: rollbackError.message,
      });
    }

    console.error('Transaction failed', {
      code: error.code,
      message: error.message,
    });

    throw error;
  } finally {
    if (!released) {
      client.release();
    }
  }
}
```

Do not use `pool.query()` for individual statements inside a transaction; different statements could run on different connections.

## Graceful shutdown

Close the pool when the process receives a termination signal:

```js
let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.info(`Received ${signal}; closing PostgreSQL pool`);

  const forceExit = setTimeout(() => {
    console.error('Timed out while closing PostgreSQL pool');
    process.exit(1);
  }, 10_000);

  forceExit.unref();

  try {
    await pool.end();
    clearTimeout(forceExit);
    console.info('PostgreSQL pool closed');
    process.exitCode = 0;
  } catch (error) {
    clearTimeout(forceExit);
    console.error('Failed to close PostgreSQL pool', error);
    process.exitCode = 1;
  }
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));
```

## Timeout roles

- `connectionTimeoutMillis`: limits how long callers wait to acquire/establish a connection.
- `idleTimeoutMillis`: removes unused connections; it does not limit query duration.
- `statement_timeout`: PostgreSQL cancels long-running SQL on the server. This is the most important query timeout.
- `query_timeout`: client-side fallback. Set it slightly higher than `statement_timeout`.
- Application/request timeout: should cover the complete operation, including pool waiting, queries, and other work.

For pool sizing, remember that `max` applies **per Node.js process**. For example, 8 application instances with `max: 10` can create up to 80 database connections. Leave capacity for migrations, administration, and background jobs. Avoid automatically retrying arbitrary failed queries; retry only known transient errors and only when the operation is safe or idempotent.

