Calls.Text:
Use the `pg` package’s `Pool`, configure finite connection/query/idle timeouts, attach a pool-level error listener, and always release checked-out clients in `finally`.

```bash
npm install pg
```

### Pool configuration

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Tune this relative to PostgreSQL's max_connections and the number
  // of application instances.
  max: Number(process.env.PG_POOL_MAX ?? 10),

  // Fail instead of waiting indefinitely for a connection.
  connectionTimeoutMillis: Number(
    process.env.PG_CONNECT_TIMEOUT_MS ?? 5_000
  ),

  // Close clients that have remained unused in the pool.
  idleTimeoutMillis: Number(
    process.env.PG_IDLE_TIMEOUT_MS ?? 30_000
  ),

  // Server-side timeout: PostgreSQL cancels long-running statements.
  statement_timeout: Number(
    process.env.PG_STATEMENT_TIMEOUT_MS ?? 10_000
  ),

  // Client-side guard, slightly longer than statement_timeout.
  query_timeout: Number(
    process.env.PG_QUERY_TIMEOUT_MS ?? 12_000
  ),

  // Prevent abandoned transactions from holding locks indefinitely.
  idle_in_transaction_session_timeout: Number(
    process.env.PG_IDLE_TRANSACTION_TIMEOUT_MS ?? 15_000
  ),

  application_name: process.env.APP_NAME ?? 'node-api',

  // Configure SSL explicitly when your database requires it.
  // Prefer a trusted CA; do not use rejectUnauthorized: false in production.
  //
  // ssl: {
  //   rejectUnauthorized: true,
  //   ca: require('fs').readFileSync(process.env.PG_CA_FILE, 'utf8'),
  // },
});

// This is required for errors emitted by idle/background clients.
// Query errors are handled by each query's try/catch.
pool.on('error', (err) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: err.message,
    code: err.code,
    stack: err.stack,
  });

  // Report to monitoring. Usually do not immediately terminate the process:
  // pg removes the failed client and can create a replacement.
});

async function query(text, values = []) {
  const startedAt = Date.now();

  try {
    return await pool.query(text, values);
  } catch (err) {
    console.error('PostgreSQL query failed', {
      code: err.code,
      message: err.message,
      durationMs: Date.now() - startedAt,
      // Avoid logging `values`; they may contain credentials or PII.
    });

    throw err;
  }
}

module.exports = { pool, query };
```

Use parameterized queries:

```js
const { query } = require('./db');

async function getUser(id) {
  const result = await query(
    'SELECT id, email FROM users WHERE id = $1',
    [id]
  );

  return result.rows[0] ?? null;
}
```

### Transactions

A transaction must use the same checked-out client for all statements. Always roll back on failure and release the client in `finally`.

```js
const { pool } = require('./db');

async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();
  let destroyClient = false;

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackErr) {
      // The connection may no longer be usable.
      destroyClient = true;
      console.error('Transaction rollback failed', rollbackErr);
    }

    throw err;
  } finally {
    // Passing true destroys an unhealthy client instead of returning it.
    client.release(destroyClient);
  }
}
```

### Graceful shutdown

```js
const { pool } = require('./db');

let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    await pool.end();
    process.exitCode = 0;
  } catch (err) {
    console.error('Failed to close PostgreSQL pool', err);
    process.exitCode = 1;
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

### Operational guidance

- Set `max` based on the total across all application instances. For example, 10 instances with `max: 10` can open roughly 100 connections.
- Monitor `pool.totalCount`, `pool.idleCount`, and `pool.waitingCount`; a sustained `waitingCount` indicates pool saturation.
- PostgreSQL reports a statement timeout with SQLSTATE `57014`.
- Do not retry every database error. Retry only known transient failures, only when the operation is safe/idempotent, and use bounded exponential backoff.
- Keep transactions short; never perform slow network calls while holding a transaction open.
- A basic readiness check can run `SELECT 1`, but avoid running it so frequently that it adds meaningful database load.

