message.content:
Use `pg`’s `Pool`, configure separate connection and query timeouts, register a pool-level error listener, and always release checked-out clients in `finally`.

```bash
npm install pg
```

### Pool configuration

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum number of connections held by this process.
  max: Number(process.env.PG_POOL_MAX ?? 10),

  // Fail if a connection cannot be established/acquired in this time.
  connectionTimeoutMillis: Number(
    process.env.PG_CONNECT_TIMEOUT_MS ?? 5_000
  ),

  // Close unused connections after this time.
  idleTimeoutMillis: Number(
    process.env.PG_IDLE_TIMEOUT_MS ?? 30_000
  ),

  // PostgreSQL server-side statement timeout. This is the primary
  // protection against queries running indefinitely.
  statement_timeout: Number(
    process.env.PG_STATEMENT_TIMEOUT_MS ?? 15_000
  ),

  // Optional node-postgres client-side query timeout.
  query_timeout: Number(
    process.env.PG_QUERY_TIMEOUT_MS ?? 20_000
  ),

  // Prevent abandoned transactions from holding locks indefinitely.
  idle_in_transaction_session_timeout: Number(
    process.env.PG_IDLE_TX_TIMEOUT_MS ?? 30_000
  ),

  // Use only when your PostgreSQL provider requires TLS.
  ssl:
    process.env.PG_SSL === 'true'
      ? { rejectUnauthorized: true }
      : undefined,
});

// Handles errors emitted by idle clients in the pool.
// Without this listener, an idle-client error can become an
// unhandled EventEmitter error.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
  });
});

async function query(text, params = []) {
  const startedAt = Date.now();

  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      // Avoid logging params if they may contain secrets or personal data.
      text,
      code: error.code,
      message: error.message,
      durationMs: Date.now() - startedAt,
    });

    throw error;
  }
}

async function checkConnection() {
  await pool.query('SELECT 1');
}

async function closePool() {
  await pool.end();
}

module.exports = {
  pool,
  query,
  checkConnection,
  closePool,
};
```

Use parameterized queries:

```js
const db = require('./db');

async function findUser(id) {
  const result = await db.query(
    'SELECT id, email FROM users WHERE id = $1',
    [id]
  );

  return result.rows[0] ?? null;
}
```

### Transactions

When using `pool.connect()`, release the client in `finally`. A transaction must use the same client for all statements.

```js
const { pool } = require('./db');

async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('PostgreSQL rollback failed', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

### Startup and graceful shutdown

```js
// server.js
const http = require('node:http');
const { checkConnection, closePool } = require('./db');

const server = http.createServer(/* your app */);

async function start() {
  try {
    await checkConnection();
    server.listen(3000, () => {
      console.log('Server listening on port 3000');
    });
  } catch (error) {
    console.error('Database startup check failed', error);
    process.exit(1);
  }
}

let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; shutting down`);

  // Stop accepting new HTTP requests first.
  server.close(async (serverError) => {
    try {
      await closePool();

      if (serverError) {
        console.error('HTTP server shutdown failed', serverError);
        process.exitCode = 1;
      }
    } catch (error) {
      console.error('PostgreSQL pool shutdown failed', error);
      process.exitCode = 1;
    }
  });
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));

start();
```

