  idleTimeoutMillis: Number(process.env.PG_IDLE_TIMEOUT_MS ?? 30_000),

  // Server-side protection: PostgreSQL cancels long statements.
  statement_timeout: Number(process.env.PG_STATEMENT_TIMEOUT_MS ?? 15_000),

  // Client-side protection. Keep it slightly above statement_timeout so the
  // server normally performs the cancellation first.
  query_timeout: Number(process.env.PG_QUERY_TIMEOUT_MS ?? 17_000),

  // Prevent abandoned transactions from retaining locks indefinitely.
  idle_in_transaction_session_timeout: Number(
    process.env.PG_IDLE_TX_TIMEOUT_MS ?? 30_000
  ),

  keepAlive: true,
  keepAliveInitialDelayMillis: 10_000,

  // Configure using your provider's CA certificate in production.
  ssl:
    process.env.PGSSL === 'true'
      ? {
          rejectUnauthorized: true,
          // ca: process.env.PG_CA_CERT,
        }
      : undefined,
});

// Required: handles errors emitted by idle clients in the pool.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
    stack: error.stack,
  });

  // Do not automatically exit here unless your operational policy requires it.
  // The pool usually removes the failed client and can create another one.
});

pool.on('connect', () => {
  console.debug('PostgreSQL connection established');
});

module.exports = pool;
```

Do not use `rejectUnauthorized: false` in production unless you explicitly accept losing certificate verification. Supply the database provider’s CA certificate instead.

### Queries

Use `pool.query()` for one-off queries. It automatically checks out and releases a connection.

```js
const pool = require('./db');

async function getUser(userId) {
  try {
    const result = await pool.query(
      'SELECT id, email, created_at FROM users WHERE id = $1',
      [userId]
    );

    return result.rows[0] ?? null;
  } catch (error) {
    console.error('Database query failed', {
      operation: 'getUser',
      userId,
      code: error.code,
      message: error.message,
    });

    // Preserve the original error/code for higher-level handling.
    throw error;
  }
}
```

Always parameterize values with `$1`, `$2`, etc.; never interpolate untrusted values into SQL.

### Transactions

Transactions must use one checked-out client. Always release it in `finally`.

```js
async function transferFunds(fromId, toId, amount) {
  let client;

  try {
    client = await pool.connect();

    await client.query('BEGIN');
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );
    await client.query('COMMIT');
  } catch (error) {
    if (client) {
      try {
        await client.query('ROLLBACK');
      } catch (rollbackError) {
        console.error('Transaction rollback failed', rollbackError);
      }
    }

    console.error('Transaction failed', {
      code: error.code,
      message: error.message,
    });

    throw error;
  } finally {
    client?.release();
  }
}
```

A leaked client eventually exhausts the pool, causing later requests to wait until `connectionTimeoutMillis` is reached.

### Graceful shutdown

Stop accepting application requests first, then close the pool:

```js
let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    // For an HTTP application, call server.close() and wait for active
    // requests to finish before pool.end().
    await pool.end();
    process.exitCode = 0;
  } catch (error) {
    console.error('Failed to close PostgreSQL pool', error);
    process.exitCode = 1;
  }
}

process.once('SIGTERM', () => void shutdown('SIGTERM'));
process.once('SIGINT', () => void shutdown('SIGINT'));
```

### Practical sizing and error-handling rules

- Set `max` based on total deployment size, not per-process convenience:
  - `(pool max × application instances) + administrative connections`
  - Keep that total below PostgreSQL’s connection limit.
- Start with `max: 10` unless load testing shows a need for more.
- Monitor:
  ```js
  console.log({
    total: pool.totalCount,
    idle: pool.idleCount,
    waiting: pool.waitingCount,
  });
  ```
- Treat PostgreSQL error code `57014` as a canceled/timed-out statement.
- Map expected database errors such as unique violations (`23505`) to appropriate application responses.
- Do not retry every database error. Retry only idempotent operations and known transient failures, with a small retry limit and exponential backoff.
- A JavaScript `Promise.race()` timeout does **not** cancel the PostgreSQL query; prefer PostgreSQL `statement_timeout` plus `query_timeout`.
- Avoid keeping transactions open while making network calls or doing unrelated work.

