  }

  private handleRetry = (): void => {
    this.props.onRetry?.();

    this.setState((state) => ({
      error: null,
      retryKey: state.retryKey + 1,
    }));
  };

  render(): ReactNode {
    const { error, retryKey } = this.state;

    if (error) {
