React error boundaries must be class components. This TypeScript implementation logs the error, displays a fallback, and remounts its children when **Retry** is clicked.

```tsx
import React, { ErrorInfo, ReactNode } from "react";

type ErrorFallbackProps = {
  error: Error | null;
  retry: () => void;
};

type ErrorBoundaryProps = {
  children: ReactNode;
  fallback?: ReactNode | ((props: ErrorFallbackProps) => ReactNode);
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
};

type ErrorBoundaryState = {
  hasError: boolean;
  error: Error | null;
  retryKey: number;
};

export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = {
    hasError: false,
    error: null,
    retryKey: 0,
  };

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return {
      hasError: true,
      error,
    };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Replace or supplement this with your logging service.
    console.error("Unhandled React render error", {
      error,
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });

    try {
      this.props.onError?.(error, errorInfo);
    } catch (loggingError) {
      console.error("Error while reporting render error", loggingError);
    }
  }

  private retry = () => {
    this.setState((state) => ({
      hasError: false,
      error: null,
      retryKey: state.retryKey + 1,
    }));
  };

  render() {
    const { children, fallback } = this.props;
    const { hasError, error, retryKey } = this.state;

    if (hasError) {
      if (typeof fallback === "function") {
        return fallback({ error, retry: this.retry });
      }

      if (fallback !== undefined) {
        return fallback;
      }

      return (
        <div role="alert" style={{ padding: 16 }}>
          <h2>Something went wrong.</h2>
          {error?.message && <p>{error.message}</p>}
          <button type="button" onClick={this.retry}>
            Retry
          </button>
        </div>
      );
    }

    // Changing the key remounts the child tree when retrying.
    return <React.Fragment key={retryKey}>{children}</React.Fragment>;
  }
}
